exercise.solution:
struct Fibonacci {
    current: u64,
    next: u64,
}

impl Default for Fibonacci {
    fn default() -> Self {
        Self { current: 0, next: 1 }
    }
}

impl Iterator for Fibonacci {
    type Item = u64;
    fn next(&mut self) -> Option<u64> {
        let value = self.current;
        (self.current, self.next) = (self.next, self.current + self.next);
        Some(value)
    }
}

fn main() {
    let values: Vec<String> = Fibonacci::default().take(12).map(|n| n.to_string()).collect();
    println!("{}", values.join(" "));
}
